// ── CH4 · THE ICE GATES — princess, snowman, fading aurora ──

svg += `<defs>
  <linearGradient id="lg-ch4" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="${isN?'#04001A':sc.sky1}"/>
    <stop offset="50%" stop-color="${isN?'#0A0830':'#2A3A5A'}"/>
    <stop offset="100%" stop-color="${isN?'#0E1A2E':sc.sky2}"/>
  </linearGradient>
  <linearGradient id="lg-ch4-castle" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="${isN?'#7AB0E0':'#C0E0FF'}"/>
    <stop offset="100%" stop-color="${isN?'#5088B8':'#90C0E0'}"/>
  </linearGradient>
</defs>`;
svg += `<rect x="0" y="0" width="${w}" height="${h}" fill="url(#lg-ch4)"/>`;

// ── FADING AURORA (weak, flickering) ──
for (let i = 0; i < 4; i++) {
  const ax = w*(0.15+i*0.22);
  const ay = h*0.06+Math.sin(mt*0.3+i*1.2)*h*0.04;
  const aCols = ['#00FF88','#7DF9FF','#DA70D6','#00CED1'];
  // Fading: lower opacity, sometimes disappearing
  const fadeFlicker = Math.sin(mt*1.5+i*2.1)*0.5+0.5;
  const aop = 0.015+fadeFlicker*0.025;
  svg += `<ellipse cx="${ax}" cy="${ay}" rx="${w*0.14}" ry="${h*0.1+Math.sin(mt*0.3+i)*h*0.03}" fill="${aCols[i]}" opacity="${aop}"/>`;
}
// Weak curtain waves
for (let i = 0; i < 2; i++) {
  const cy2 = h*0.1+i*h*0.03;
  const sway = Math.sin(mt*0.5+i*1.5)*w*0.04;
  const cop = 0.04+Math.sin(mt*0.8+i)*0.03;
  svg += `<path d="M0 ${cy2} Q${w*0.25+sway} ${cy2-10} ${w*0.5} ${cy2+3} T${w} ${cy2}" fill="none" stroke="rgba(125,249,255,${cop})" stroke-width="${2+i}"/>`;
}

// Stars
for (let i = 0; i < 35; i++) {
  const sx = (Math.sin(i*127.1+3.7)*0.5+0.5)*w;
  const sy = (Math.sin(i*311.7+1.3)*0.5+0.5)*h*0.35;
  const sr = 0.5+Math.sin(mt*1.2+i*0.9)*0.4;
  const sop = isN?0.6+Math.sin(mt+i*0.5)*0.3:0.12;
  svg += `<circle cx="${sx}" cy="${sy}" r="${sr}" fill="#FFF" opacity="${sop}"/>`;
}

// ── Snow ground ──
svg += `<path d="M0 ${bY-8} Q${w*0.2} ${bY-15} ${w*0.4} ${bY-5} Q${w*0.6} ${bY-12} ${w*0.8} ${bY-3} Q${w*0.9} ${bY-10} ${w} ${bY-6} L${w} ${h} L0 ${h} Z" fill="${sc.ground}" stroke="#C0D8F0" stroke-width="${ol*0.4}"/>`;
for (let i = 0; i < 15; i++) {
  const spx = w*(0.03+i*0.065);
  const spy = bY+3+Math.sin(i*2.1)*6;
  const spop = 0.25+Math.sin(mt*2.5+i*1.7)*0.2;
  svg += `<circle cx="${spx}" cy="${spy}" r="1.2" fill="#FFF" opacity="${spop}"/>`;
}

// ── LARGE ICE CASTLE (center-right, imposing) ──
const cx = w*0.6;
const cy = bY-8;
const castleH = 130+w2*10;

// Main body
svg += `<rect x="${cx-45}" y="${cy-castleH*0.5}" width="90" height="${castleH*0.5+8}" rx="3" fill="url(#lg-ch4-castle)" stroke="#80B0D0" stroke-width="${ol}"/>`;
// Gate (arched)
svg += `<path d="M${cx-12} ${cy} L${cx-12} ${cy-20} Q${cx} ${cy-32} ${cx+12} ${cy-20} L${cx+12} ${cy}" fill="${isN?'rgba(125,249,255,0.3)':'rgba(100,180,220,0.25)'}" stroke="#80B0D0" stroke-width="${ol*0.5}"/>`;
// Left tower
svg += `<rect x="${cx-68}" y="${cy-castleH*0.7}" width="28" height="${castleH*0.7+8}" rx="2" fill="url(#lg-ch4-castle)" stroke="#80B0D0" stroke-width="${ol}"/>`;
svg += `<polygon points="${cx-68},${cy-castleH*0.7} ${cx-54},${cy-castleH*0.7-25} ${cx-40},${cy-castleH*0.7}" fill="#A0D8F0" stroke="#80B0D0" stroke-width="${ol*0.6}"/>`;
// Right tower (tallest)
svg += `<rect x="${cx+40}" y="${cy-castleH*0.85}" width="28" height="${castleH*0.85+8}" rx="2" fill="url(#lg-ch4-castle)" stroke="#80B0D0" stroke-width="${ol}"/>`;
svg += `<polygon points="${cx+40},${cy-castleH*0.85} ${cx+54},${cy-castleH*0.85-30} ${cx+68},${cy-castleH*0.85}" fill="#A0D8F0" stroke="#80B0D0" stroke-width="${ol*0.6}"/>`;
// Battlements
for (let i = 0; i < 8; i++) svg += `<rect x="${cx-42+i*11}" y="${cy-castleH*0.5-8}" width="6" height="8" rx="1" fill="url(#lg-ch4-castle)" stroke="#80B0D0" stroke-width="${ol*0.4}"/>`;

// Windows with FADING glow (magic is weakening)
const winPos = [[-54,cy-castleH*0.55],[-54,cy-castleH*0.35],[-25,cy-castleH*0.35],[0,cy-castleH*0.3],[25,cy-castleH*0.35],[54,cy-castleH*0.65],[54,cy-castleH*0.45],[54,cy-castleH*0.25]];
for (let i = 0; i < 8; i++) {
  const wxp = cx+winPos[i][0];
  const wyp = winPos[i][1];
  const pulse = Math.sin(mt*1.5+i*1.1)*0.5+0.5;
  // Fading: windows flicker between bright and dim
  const fade = Math.sin(mt*0.4+i*0.7)*0.5+0.5;
  const intensity = 0.2+pulse*0.3*fade;
  svg += `<rect x="${wxp-3}" y="${wyp}" width="6" height="9" rx="3" fill="rgba(125,249,255,${intensity})" stroke="#80B0D0" stroke-width="${ol*0.3}"/>`;
  if (intensity>0.35) svg += `<ellipse cx="${wxp}" cy="${wyp+4}" rx="8" ry="6" fill="rgba(125,249,255,${intensity*0.06})"/>`;
}

// FADING CRYSTAL on top tower (pulsing weak)
const crystalY = cy-castleH*0.85-32;
const crystalPulse = Math.sin(mt*1.2)*0.5+0.5;
const crystalOp = 0.15+crystalPulse*0.2;
svg += `<polygon points="${cx+54},${crystalY} ${cx+51},${crystalY+8} ${cx+57},${crystalY+8}" fill="${sc.acc}" opacity="${crystalOp+0.2}"/>`;
svg += `<circle cx="${cx+54}" cy="${crystalY+3}" r="${8+crystalPulse*5}" fill="${sc.acc}" opacity="${crystalOp*0.3}"/>`;
// Fading sparks falling from crystal
for (let i = 0; i < 5; i++) {
  const fsx = cx+54+Math.sin(mt*2+i*1.3)*6;
  const fsy = crystalY+10+(mt*15+i*12)%30;
  const fsop = 0.3-((mt*15+i*12)%30)/30*0.3;
  svg += `<circle cx="${fsx}" cy="${fsy}" r="1" fill="${sc.acc}" opacity="${fsop}"/>`;
}

// ═══ CHARACTERS ═══

// ── PRINCESS (at the gate, reaching out) ──
const prx = cx-5, pry = cy-5;
svg += `<polygon points="${prx},${pry-28} ${prx-14},${pry} ${prx+14},${pry}" fill="${isN?'#6A5ACD':'#87CEEB'}" stroke="${isN?'#483D8B':'#5F9EA0'}" stroke-width="${ol*0.5}" opacity="0.85"/>`;
// Cape
const cpFlow = Math.sin(mt*1.0)*7;
svg += `<path d="M${prx+4} ${pry-24} Q${prx+16+cpFlow} ${pry-18} ${prx+12+cpFlow*1.5} ${pry-3}" fill="none" stroke="${isN?'#9370DB':'#ADD8E6'}" stroke-width="3" stroke-linecap="round" opacity="0.65"/>`;
svg += `<circle cx="${prx}" cy="${pry-33}" r="6" fill="#FFDAB9" stroke="#DEB887" stroke-width="${ol*0.3}"/>`;
// Braid
const brSw = Math.sin(mt*0.9)*3;
svg += `<path d="M${prx+4} ${pry-31} Q${prx+10+brSw} ${pry-22} ${prx+8+brSw*1.2} ${pry-12}" fill="none" stroke="#F5DEB3" stroke-width="3" stroke-linecap="round"/>`;
// Crown
svg += `<path d="M${prx-5} ${pry-38} L${prx-3} ${pry-42} L${prx} ${pry-39} L${prx+3} ${pry-42} L${prx+5} ${pry-38}" fill="none" stroke="${sc.acc}" stroke-width="1.5"/>`;
// Reaching hand out
svg += `<line x1="${prx-12}" y1="${pry-20}" x2="${prx-22}" y2="${pry-25+Math.sin(mt*1.5)*3}" stroke="#FFDAB9" stroke-width="2" stroke-linecap="round"/>`;
// Weak magic from hand
const mgR = 2+w3*2;
svg += `<circle cx="${prx-23}" cy="${pry-25}" r="${mgR}" fill="${sc.acc}" opacity="${0.15+w1*0.15}"/>`;

// ── SNOWMAN (beside gate, waving) ──
const smx = cx+25, smy = cy;
svg += `<circle cx="${smx}" cy="${smy-2}" r="14" fill="#F8F8FF" stroke="#C8D8E8" stroke-width="${ol*0.5}"/>`;
svg += `<circle cx="${smx}" cy="${smy-22}" r="10" fill="#F8F8FF" stroke="#C8D8E8" stroke-width="${ol*0.5}"/>`;
svg += `<circle cx="${smx}" cy="${smy-38}" r="8" fill="#F8F8FF" stroke="#C8D8E8" stroke-width="${ol*0.5}"/>`;
svg += `<circle cx="${smx-3}" cy="${smy-40}" r="1.5" fill="#2A2A2A"/>`;
svg += `<circle cx="${smx+3}" cy="${smy-40}" r="1.5" fill="#2A2A2A"/>`;
svg += `<polygon points="${smx},${smy-37} ${smx+7},${smy-36} ${smx},${smy-35}" fill="#FF8C42"/>`;
svg += `<path d="M${smx-3} ${smy-33} Q${smx} ${smy-31} ${smx+3} ${smy-33}" fill="none" stroke="#2A2A2A" stroke-width="1"/>`;
for (let i = 0; i < 3; i++) svg += `<circle cx="${smx}" cy="${smy-16+i*6}" r="1.5" fill="#2A2A2A"/>`;
// Waving arm!
const wave = Math.sin(mt*3)*15;
svg += `<line x1="${smx+10}" y1="${smy-24}" x2="${smx+26}" y2="${smy-35+wave}" stroke="#6B4F2A" stroke-width="2" stroke-linecap="round"/>`;
svg += `<line x1="${smx-10}" y1="${smy-24}" x2="${smx-24}" y2="${smy-32}" stroke="#6B4F2A" stroke-width="2" stroke-linecap="round"/>`;
svg += `<rect x="${smx-6}" y="${smy-50}" width="12" height="10" rx="1" fill="#2A2A3A"/>`;
svg += `<rect x="${smx-9}" y="${smy-41}" width="18" height="3" rx="1" fill="#2A2A3A"/>`;

// ── Three pups (arriving from left, looking up in wonder) ──
const pArr = [{x:w*0.18,c:'#FF8C42',s:'#D06B20',e:'#E07830'},{x:w*0.12,c:'#9370DB',s:'#7B5EA7',e:'#8060C0'},{x:w*0.06,c:'#5AAA5A',s:'#3A8A3A',e:'#4A9A4A'}];
for (let p = 0; p < 3; p++) {
  const ppx = pArr[p].x, ppy = cy+2+p;
  svg += `<ellipse cx="${ppx}" cy="${ppy-4}" rx="6.5" ry="4.5" fill="${pArr[p].c}" stroke="${pArr[p].s}" stroke-width="${ol*0.4}"/>`;
  // Head tilted UP (looking at castle)
  svg += `<circle cx="${ppx+5}" cy="${ppy-10}" r="4.5" fill="${pArr[p].c}" stroke="${pArr[p].s}" stroke-width="${ol*0.4}"/>`;
  svg += `<polygon points="${ppx+2},${ppy-14} ${ppx+1},${ppy-19} ${ppx+5},${ppy-15}" fill="${pArr[p].e}"/>`;
  svg += `<polygon points="${ppx+8},${ppy-14} ${ppx+9},${ppy-19} ${ppx+6},${ppy-15}" fill="${pArr[p].e}"/>`;
  // Wide eyes (amazed)
  svg += `<circle cx="${ppx+4}" cy="${ppy-11}" r="1.3" fill="#222"/>`;
  svg += `<circle cx="${ppx+7}" cy="${ppy-11}" r="1.3" fill="#222"/>`;
  // Wagging tail (excited)
  const ptail = Math.sin(mt*5+p*1.5)*10;
  svg += `<path d="M${ppx-7} ${ppy-5} Q${ppx-12} ${ppy-13+ptail} ${ppx-10} ${ppy-17+ptail*0.5}" fill="none" stroke="${pArr[p].c}" stroke-width="2.5" stroke-linecap="round"/>`;
}

// ── Deer & fawn (behind pups) ──
const ddx2 = w*0.02, ddy2 = cy-2;
svg += `<ellipse cx="${ddx2+15}" cy="${ddy2}" rx="12" ry="8" fill="#C4862D" stroke="#A06820" stroke-width="${ol*0.3}"/>`;
svg += `<path d="M${ddx2+22} ${ddy2-5} Q${ddx2+26} ${ddy2-15} ${ddx2+24} ${ddy2-22}" fill="none" stroke="#C4862D" stroke-width="5" stroke-linecap="round"/>`;
svg += `<circle cx="${ddx2+24}" cy="${ddy2-25}" r="4" fill="#D4964A"/>`;
svg += `<circle cx="${ddx2+26}" cy="${ddy2-26}" r="0.8" fill="#222"/>`;

// ── Owl perched on castle battlement ──
const olx = cx-35, oly = cy-castleH*0.5-12;
svg += `<ellipse cx="${olx}" cy="${oly+2}" rx="6" ry="7" fill="#8B6B4A"/>`;
svg += `<circle cx="${olx}" cy="${oly-5}" r="5" fill="#9B7B5A"/>`;
svg += `<circle cx="${olx-2}" cy="${oly-6}" r="2.5" fill="#FFD700"/>`;
svg += `<circle cx="${olx+2}" cy="${oly-6}" r="2.5" fill="#FFD700"/>`;
svg += `<circle cx="${olx-2}" cy="${oly-6}" r="1" fill="#222"/>`;
svg += `<circle cx="${olx+2}" cy="${oly-6}" r="1" fill="#222"/>`;
svg += `<polygon points="${olx-4},${oly-9} ${olx-2},${oly-15} ${olx},${oly-9}" fill="#7B5B3A"/>`;
svg += `<polygon points="${olx},${oly-9} ${olx+2},${oly-15} ${olx+4},${oly-9}" fill="#7B5B3A"/>`;

// ── Golden butterfly (hovering near crystal) ──
const bfx4 = cx+54+Math.sin(mt*0.8)*12;
const bfy4 = crystalY+15+Math.cos(mt*0.6)*8;
const bfW4 = Math.sin(mt*7)*5;
svg += `<ellipse cx="${bfx4-3}" cy="${bfy4}" rx="${3.5+bfW4*0.3}" ry="4.5" fill="#FFD700" opacity="0.85" transform="rotate(${-bfW4*2} ${bfx4-3} ${bfy4})"/>`;
svg += `<ellipse cx="${bfx4+3}" cy="${bfy4}" rx="${3.5+bfW4*0.3}" ry="4.5" fill="#FFD700" opacity="0.85" transform="rotate(${bfW4*2} ${bfx4+3} ${bfy4})"/>`;
svg += `<ellipse cx="${bfx4}" cy="${bfy4}" rx="0.8" ry="3" fill="#8B6914"/>`;
svg += `<circle cx="${bfx4}" cy="${bfy4}" r="${8+w3*4}" fill="#FFD700" opacity="${0.04+w1*0.03}"/>`;

// Snowflakes
for (let i = 0; i < 18; i++) {
  const sfx = (Math.sin(i*73.1+5.3)*0.5+0.5)*w+Math.sin(mt*0.7+i*0.5)*10;
  const sfy = ((mt*7+i*(h/18))%(h+20))-10;
  svg += `<circle cx="${sfx%w}" cy="${sfy}" r="${1+Math.sin(i*2.3)*0.5}" fill="#FFF" opacity="${0.3+Math.sin(mt*1.5+i*0.7)*0.2}"/>`;
}

if (!isN) {
  svg += `<circle cx="${w*0.12}" cy="${h*0.12}" r="${30+w1*8}" fill="#FFF8E0" opacity="0.08"/>`;
  svg += `<circle cx="${w*0.12}" cy="${h*0.12}" r="16" fill="#FFF8E0" opacity="0.3"/>`;
} else {
  svg += `<circle cx="${w*0.12}" cy="${h*0.1}" r="14" fill="#EDE8DF" opacity="0.75"/>`;
  svg += `<circle cx="${w*0.12+4}" cy="${h*0.1-3}" r="11" fill="#04001A" opacity="0.9"/>`;
}
